    SELECT location_id
    FROM locations
    WHERE lower(name) = lower('The Syndicate at the University Union')
    LIMIT 1
),
inserted_import_location AS (
    INSERT INTO locations (name, description, coordinates)
    SELECT
        'The Syndicate at the University Union',
        'Auto-created from UNT calendar event import.',
        ST_SetSRID(
            ST_MakePoint(-97.147274, 33.210932),
            4326
        )
    WHERE NOT EXISTS (
        SELECT 1 FROM existing_import_location
    )
    RETURNING location_id
),
resolved_location AS (
    SELECT location_id FROM existing_import_location
    UNION ALL
    SELECT location_id FROM inserted_import_location
    LIMIT 1
),
existing_event AS (
    SELECT e.event_id
    FROM events e
    JOIN event_details d ON d.event_id = e.event_id
    WHERE d.metadata ->> 'source_uid' = 'tag:localist.com,2008:EventInstance_51737318216472'
      AND COALESCE(d.metadata ->> 'source_recurrence_id', '') = ''
    LIMIT 1
),
updated_existing_event AS (
    UPDATE events
    SET
        title = 'Jazz Chamber Music - Steve''s Combo',
        description = 'Important Links and Information 

 

Program will be announced from the stage. 

 

Livestream is not available for this event.  

 

This event is free and open to the public with general seating.',
        location_id = (SELECT location_id FROM resolved_location),
        start_date_time = TIMESTAMP '2026-04-02 12:00:00',
        end_date_time = TIMESTAMP '2026-04-02 13:00:00',
        event_type = 'Social & Entertainment',
        status = 'SCHEDULED'::event_status,
        updated_at = CURRENT_TIMESTAMP
    WHERE event_id IN (SELECT event_id FROM existing_event)
    RETURNING event_id
),
inserted_event AS (
    INSERT INTO events (
        title,
        description,
        location_id,
        start_date_time,
        end_date_time,
        event_type,
        status
    )
    SELECT
        'Jazz Chamber Music - Steve''s Combo',
        'Important Links and Information 

 

Program will be announced from the stage. 

 

Livestream is not available for this event.  

 

This event is free and open to the public with general seating.',
        (SELECT location_id FROM resolved_location),
        TIMESTAMP '2026-04-02 12:00:00',
        TIMESTAMP '2026-04-02 13:00:00',
        'Social & Entertainment',
        'SCHEDULED'::event_status
    WHERE NOT EXISTS (SELECT 1 FROM existing_event)
    RETURNING event_id
),
resolved_event AS (
    SELECT event_id FROM inserted_event
    UNION ALL
    SELECT event_id FROM updated_existing_event
    LIMIT 1
),
upserted_details AS (
    INSERT INTO event_details (
        event_id,
        source_url,
        source_location_name,
        room_detail,
        metadata
    )
    SELECT
        (SELECT event_id FROM resolved_event),
        'https://calendar.unt.edu/event/jazz-chamber-music-steves-combo1',
        'The Syndicate at the University Union',
        NULL,
        '{"all_day": false, "categories": ["Social & Entertainment"], "source_geo": {"latitude": 33.210932, "longitude": -97.147274}, "source_recurrence_id": "", "source_status": "SCHEDULED", "source_uid": "tag:localist.com,2008:EventInstance_51737318216472"}'::jsonb
    WHERE EXISTS (SELECT 1 FROM resolved_event)
    ON CONFLICT (event_id) DO UPDATE
    SET
        source_url = EXCLUDED.source_url,
        source_location_name = EXCLUDED.source_location_name,
        room_detail = EXCLUDED.room_detail,
        metadata = EXCLUDED.metadata,
        updated_at = CURRENT_TIMESTAMP
    RETURNING event_id
)
SELECT event_id FROM resolved_event;

