WITH
resolved_location AS (
    SELECT 'a8f9895a-f160-40bd-a5c8-058b9e0f4476'::uuid AS location_id
),
existing_event AS (
    SELECT e.event_id
    FROM events e
    JOIN event_details d ON d.event_id = e.event_id
    WHERE d.metadata ->> 'source_uid' = 'tag:localist.com,2008:EventInstance_51992804745597'
      AND COALESCE(d.metadata ->> 'source_recurrence_id', '') = ''
    LIMIT 1
),
updated_existing_event AS (
    UPDATE events
    SET
        title = 'Masters Recital : Yiyang Hu, piano',
        description = 'Important Links and Information 

 

Program  

Please note, this program is subject to change. Final program will be available by the day of the performance. 

 

Livestream is not available for this event.

 

This event is free and open to the public with general seating.',
        location_id = (SELECT location_id FROM resolved_location),
        start_date_time = TIMESTAMP '2026-04-09 14:00:00',
        end_date_time = TIMESTAMP '2026-04-09 15:00:00',
        event_type = 'Social & Entertainment',
        status = 'SCHEDULED'::event_status,
        updated_at = CURRENT_TIMESTAMP
