        'Social & Entertainment',
        'SCHEDULED'::event_status
    WHERE NOT EXISTS (SELECT 1 FROM existing_event)
    RETURNING event_id
),
resolved_event AS (
    SELECT event_id FROM inserted_event
    UNION ALL
    SELECT event_id FROM updated_existing_event
    LIMIT 1
),
upserted_details AS (
    INSERT INTO event_details (
        event_id,
        source_url,
        source_location_name,
        room_detail,
        metadata
    )
    SELECT
        (SELECT event_id FROM resolved_event),
        'https://calendar.unt.edu/event/masters-recital-yiyang-hu-piano-9538',
        'Paul Voertman Concert Hall at the Music Building',
        NULL,
