-- Location match: Terrill Hall, 120 -> Terrill Hall (TH) (0116f9bf-cfe7-46a6-8977-808bd7423a87)
-- Match reason: exact alias match on 'terrill hall'
WITH
resolved_location AS (
    SELECT '0116f9bf-cfe7-46a6-8977-808bd7423a87'::uuid AS location_id
),
existing_event AS (
    SELECT e.event_id
    FROM events e
    JOIN event_details d ON d.event_id = e.event_id
    WHERE d.metadata ->> 'source_uid' = 'tag:localist.com,2008:EventInstance_52135397959004'
      AND COALESCE(d.metadata ->> 'source_recurrence_id', '') = ''
    LIMIT 1
),
updated_existing_event AS (
    UPDATE events
    SET
        title = 'NABJ Semester Events',
        description = '1. Valentine''s Day Card Creating/Speed Date Interviews - Feb. 9: This event is a social event for members to come together to congregate and create a festive holiday card and also engage in interview skill work.

2. Black Voices in News/Skill Lab - Feb. 23: This is an event where a professional newsperson will come to speak with the membership about their industry experiences and provide skill insights.

3. Black Women in Journalism/Headline Writing - March 16: This is an event where a professional newswoman will speak with the membership about her industry experiences and give advice on how to write proper and eye-catching headlines.

4. Family Feud Part 2/Photowalk Submissions - March 23: This is an event where members will play in a feux journalism based game of Family Feud and discuss and choose the submissions for the Photowalk.

5. Journalism Escape Room - April 6: This is an event where the Board will devise an escape room activity for the membership based on journalism skills.

6. Election Day Meeting - April 20: This is an event where the membership will elect the Executive Board for next semester.',
        location_id = (SELECT location_id FROM resolved_location),
        start_date_time = TIMESTAMP '2026-04-20 19:00:00',
        end_date_time = TIMESTAMP '2026-04-20 20:30:00',
        event_type = 'Student Life',
        status = 'SCHEDULED'::event_status,
        updated_at = CURRENT_TIMESTAMP
    WHERE event_id IN (SELECT event_id FROM existing_event)
    RETURNING event_id
),
inserted_event AS (
    INSERT INTO events (
        title,
        description,
        location_id,
        start_date_time,
        end_date_time,
        event_type,
        status
    )
    SELECT
        'NABJ Semester Events',
        '1. Valentine''s Day Card Creating/Speed Date Interviews - Feb. 9: This event is a social event for members to come together to congregate and create a festive holiday card and also engage in interview skill work.

2. Black Voices in News/Skill Lab - Feb. 23: This is an event where a professional newsperson will come to speak with the membership about their industry experiences and provide skill insights.

3. Black Women in Journalism/Headline Writing - March 16: This is an event where a professional newswoman will speak with the membership about her industry experiences and give advice on how to write proper and eye-catching headlines.

4. Family Feud Part 2/Photowalk Submissions - March 23: This is an event where members will play in a feux journalism based game of Family Feud and discuss and choose the submissions for the Photowalk.

5. Journalism Escape Room - April 6: This is an event where the Board will devise an escape room activity for the membership based on journalism skills.

6. Election Day Meeting - April 20: This is an event where the membership will elect the Executive Board for next semester.',
        (SELECT location_id FROM resolved_location),
        TIMESTAMP '2026-04-20 19:00:00',
        TIMESTAMP '2026-04-20 20:30:00',
        'Student Life',
        'SCHEDULED'::event_status
    WHERE NOT EXISTS (SELECT 1 FROM existing_event)
    RETURNING event_id
),
resolved_event AS (
    SELECT event_id FROM inserted_event
    UNION ALL
    SELECT event_id FROM updated_existing_event
    LIMIT 1
),
upserted_details AS (
    INSERT INTO event_details (
        event_id,
        source_url,
        source_location_name,
        room_detail,
        metadata
    )
    SELECT
        (SELECT event_id FROM resolved_event),
        'https://calendar.unt.edu/event/nabj-semester-events-7281',
        'Terrill Hall, 120',
        '120',
        '{"all_day": false, "categories": ["Student Life"], "source_geo": {"latitude": 33.213174, "longitude": -97.149549}, "source_recurrence_id": "", "source_status": "SCHEDULED", "source_uid": "tag:localist.com,2008:EventInstance_52135397959004"}'::jsonb
    WHERE EXISTS (SELECT 1 FROM resolved_event)
    ON CONFLICT (event_id) DO UPDATE
    SET
        source_url = EXCLUDED.source_url,
        source_location_name = EXCLUDED.source_location_name,
        room_detail = EXCLUDED.room_detail,
        metadata = EXCLUDED.metadata,
        updated_at = CURRENT_TIMESTAMP
    RETURNING event_id
)
SELECT event_id FROM resolved_event;

